import{_ as a,o as t,c as s,ae as r}from"./chunks/framework.DQC_QtFV.js";const p=JSON.parse('{"title":"Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/workspace.md","filePath":"en/guide/console/workspace.md","lastUpdated":1793162416000}'),n={name:"en/guide/console/workspace.md"};function o(i,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h1><p>Three cards: environment variables, Skills, MCP servers. The first two are what the sandbox&#39;s commands can touch; the third is the external functions the assistant can call.</p><h2 id="环境变量-environment-variables" tabindex="-1">环境变量: environment variables <a class="header-anchor" href="#环境变量-environment-variables" aria-label="Permalink to &quot;环境变量: environment variables&quot;">​</a></h2><p>Every command in the sandbox runs with these variables. A variable has a name and one of two kinds, 明文 (plain) or 保密 (secret); a secret is write-only, and any secret value is scrubbed from every result that reaches the model or the log as <code>[已隐藏:名字]</code> - a message carrying one is refused in code, before Jev.</p><ul><li>The name must be a shell variable name (a letter first, at most 64 characters).</li><li>The sandbox&#39;s own fixed entries cannot be overridden: <code>PATH</code>, <code>HOME</code>, the proxy settings, <code>LD_PRELOAD</code> and the rest are the host&#39;s to set, not the model&#39;s, and the page names the rule.</li><li>A secret value must be at least 8 characters, so the scrubber cannot match ordinary text.</li></ul><p>A change applies to the next command; nothing is rebuilt.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Skills install into <code>/workspace/skills</code>, and <strong>the model can read, edit and add them itself</strong>. This card manages the <em>sources</em>: an address the installer keeps current on an interval.</p><ul><li>An address is a GitHub shorthand (<code>owner/repo</code>) or an <code>https://</code> git address. An SSH address, a local path or a URL that points at a file rather than a repository is refused with the reason - the proxy tunnels only 443, and nothing outside the workspace is visible to the sandbox.</li><li>The interval is 1 to 365 days, 7 by default.</li><li>Each row shows the commit it was installed at, when it last updated, and 正常 / 失败; a failure carries the reason and also appears in 概览&#39;s 待处理. 立即更新 runs the install now; 移除 drops the source while the skills it installed stay in the workspace.</li></ul><h2 id="mcp-服务器-mcp-servers" tabindex="-1">MCP 服务器: MCP servers <a class="header-anchor" href="#mcp-服务器-mcp-servers" aria-label="Permalink to &quot;MCP 服务器: MCP servers&quot;">​</a></h2><p>The model reaches a server only through <code>code_exec</code>, as <code>tools[&quot;server.function&quot;](args)</code>; a function&#39;s name is looked up with <code>tool_search</code> first. The system prompt carries one line per server, frozen with the window, so disabling a server or a function does not change that line - the call is refused with the rule instead.</p><ul><li>添加 / 编辑 / 停用 / 删除, one row per server: status (connected / needs_auth / error), the function count, how many are switched off, the transport and the authorization state.</li><li>A row expands in place into the functions that server offers: name, description, parameters and a switch each.</li><li>Three transports: Streamable HTTP, SSE and stdio (a stdio one runs in the sandbox and reaches the network only through the proxy).</li><li>Three auth modes: none, headers (a header&#39;s value is the <em>name</em> of an <a href="#环境变量-environment-variables">environment variable</a>, read at connect time, never stored or returned) and OAuth.</li><li>A server name is a lowercase identifier so a script never has to quote it; technical values (addresses, commands, client ids) are English letters, digits and punctuation only, the form states the rule under the field and holds the save until it is met.</li></ul><p>The OAuth flow has its own page: <a href="./../mcp.html">MCP client</a>.</p>',13)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
